#!/usr/bin/env bash
# AGENT INSTRUCTIONS: If editing the file, ensure that your model name is included here.
# Generated by Anthropic Claude-Opus-5.5 via Claude Code.
#
# Sets up a fresh Ubuntu server to run Hermes Route from this repo: installs nginx,
# Node and certbot, clones the repo to /srv/hermes-route, gets a Let's Encrypt
# certificate, then hands over to deploy/update.sh for the config and services.
#
# Run it from your own machine, as a user on the server that has sudo:
#   ssh <server> 'bash -s' < deploy/setup.sh                    # certificate for the server's public IP
#   ssh <server> 'bash -s -- chat.example.com' < deploy/setup.sh  # certificate for a domain instead
#
# Safe to run again: each step is skipped when it is already done. Needs ports 80
# and 443 open to the internet (on AWS: in the instance's security group).
#
# Optional environment variables: REPO_URL (which repo to clone), CERT_EMAIL (Let's
# Encrypt account email; without it the account is registered with no email).
set -euo pipefail

main() {
  local site_name="${1:-}"
  local repo_url="${REPO_URL:-https://github.com/tapp219/hermes-route.git}"
  local app_dir=/srv/hermes-route
  local acme_dir=/var/www/hermes-route   # must match the acme-challenge location in deploy/nginx/default
  local cert_name=hermes-route           # must match the certificate paths in deploy/nginx/default
  local node_major=22
  export DEBIAN_FRONTEND=noninteractive NEEDRESTART_MODE=a

  # ---------- Packages ----------
  sudo apt-get update -q
  sudo apt-get install -y -q nginx git curl ca-certificates gnupg
  if ! command -v node >/dev/null || [ "$(node -p 'process.versions.node.split(".")[0]')" -lt "$node_major" ]; then
    curl -fsSL "https://deb.nodesource.com/setup_${node_major}.x" | sudo -E bash -
    sudo apt-get install -y -q nodejs
  fi
  sudo apt-mark manual nodejs >/dev/null   # so `apt autoremove` never takes Node away
  if ! command -v certbot >/dev/null; then
    sudo snap install --classic certbot
    sudo ln -sf /snap/bin/certbot /usr/local/bin/certbot
  fi

  # ---------- The repo ----------
  sudo install -d -o "$USER" -g "$USER" -m 755 "$app_dir" "$acme_dir"
  if [ ! -d "$app_dir/.git" ]; then
    git clone "$repo_url" "$app_dir"
  fi

  # ---------- Certificate ----------
  # The repo's nginx config needs the certificate to exist before nginx will load it, so
  # the first time round a minimal HTTP-only site answers Let's Encrypt's challenge.
  if ! sudo test -e "/etc/letsencrypt/live/$cert_name/fullchain.pem"; then
    if [ -z "$site_name" ]; then
      # No name given: use this server's public IP (asked from the cloud metadata service, else from outside)
      local token
      token=$(curl -s -m 3 -X PUT http://169.254.169.254/latest/api/token -H 'X-aws-ec2-metadata-token-ttl-seconds: 60' || true)
      site_name=$(curl -s -m 3 -H "X-aws-ec2-metadata-token: $token" http://169.254.169.254/latest/meta-data/public-ipv4 || true)
      [[ "$site_name" =~ ^[0-9.]+$ ]] || site_name=$(curl -4 -s -m 8 https://checkip.amazonaws.com)
    fi
    [ -n "$site_name" ] || { echo "Could not work out this server's public address; pass it as an argument." >&2; exit 1; }

    sudo tee /etc/nginx/sites-available/default >/dev/null <<EOF
# Temporary: only here so Let's Encrypt can verify this server. deploy/update.sh replaces it.
server {
    listen 80 default_server;
    listen [::]:80 default_server;
    server_name _;
    location /.well-known/acme-challenge/ { root $acme_dir; }
    location / { return 503; }
}
EOF
    sudo nginx -t
    sudo systemctl reload nginx

    local target=(-d "$site_name") account=(--register-unsafely-without-email)
    # Certificates for a bare IP address only come in Let's Encrypt's short-lived profile
    [[ "$site_name" =~ ^[0-9.]+$ ]] && target=(--ip-address "$site_name" --preferred-profile shortlived)
    [ -n "${CERT_EMAIL:-}" ] && account=(-m "$CERT_EMAIL")
    sudo certbot certonly -n --agree-tos "${account[@]}" --webroot -w "$acme_dir" \
      --cert-name "$cert_name" "${target[@]}" --deploy-hook "systemctl reload nginx"
  fi

  # ---------- Config and services (the same script every later deploy uses) ----------
  "$app_dir/deploy/update.sh"
  sudo systemctl enable signal nginx

  echo
  echo "Done. Hermes Route is being served over HTTPS${site_name:+ at https://$site_name/}"
}

main "$@"
